export const compactSocials=()=>`<div class="social-short" aria-label="Redes sociales de CieloAzul">${socials.map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener" aria-label="CieloAzul en ${e(s.name)} (abre otra pestaña)"><span aria-hidden="true">${s.mark}</span><span>${e(s.name)}</span></a>`).join('')}</div>`;
export const socialSection=()=>`<section class="social-section" id="redes"><div class="wrap social-layout"><div><p class="eyebrow">SIGAMOS VIAJANDO JUNTOS</p><h2>Un poquito de CieloAzul<br>en tu día a día.</h2><p>Encuentra más inspiración, novedades y publicaciones en nuestras redes.</p><span class="social-signature">Tu pasaporte a la felicidad.</span></div><div class="social-grid">${socials.map(s=>`<a class="social-card ${s.color}" href="${e(s.url)}" target="_blank" rel="noopener"><span class="social-icon" aria-hidden="true">${s.mark}</span><div><h3>${e(s.name)}</h3><p>${e(s.description)}</p></div><span aria-hidden="true">↗</span><span class="sr-only">Abre otra pestaña</span></a>`).join('')}</div></div></section>`;
export const quickTypes=()=>`<nav class="wrap experience-shortcuts" aria-label="Tipos de paquetes">${experiences.map(x=>`<a href="${x.href}"><span aria-hidden="true">${x.icon}</span>${x.name}</a>`).join('')}</nav>`;
export const experienceSection=()=>`<section class="wrap section experiences" id="experiencias"><p class="eyebrow">TANTAS FORMAS DE VIAJAR COMO DE SOÑAR</p><div class="section-heading"><h2>¿Qué viaje tienes en mente?</h2><p>De una escapada a una gran celebración.<br>Encuentra tu forma de viajar con CieloAzul.</p></div><div class="experience-grid">${experiences.map((x,i)=>`<article class="experience-card"><img src="/assets/${x.image}" alt="" width="525" height="700" loading="lazy"><div><span class="experience-number">0${i+1} / ${x.short}</span><h3>${x.name}</h3><p>${x.text}</p><a href="${x.href}">${i<2?'Explorar paquetes':'Solicitar opciones'} <span aria-hidden="true">↗</span></a></div></article>`).join('')}</div><p class="muted">Fotografías ilustrativas. Los servicios y la disponibilidad se confirman en cada propuesta.</p></section>`;
export function flyerSection(trips){return `<section class="brochure-section" id="carteles"><div class="wrap section"><p class="eyebrow">LOS VIAJES QUE YA CONOCES, CON TODOS SUS DETALLES</p><div class="section-heading"><h2>Tu boleto de abordar<br>a la felicidad.</h2><p>Conservamos los carteles de CieloAzul.<br>Ábrelos para ver sus fotos e información completa.</p></div><div class="brochure-grid">${Object.entries(flyers).map(([id,f])=>{const t=trips.find(t=>t.id===id);return `<article class="brochure-card"><a href="/viajes/${id}/#cartel" class="brochure-image"><img src="/assets/${f.file}" alt="Cartel original de ${e(t.hotel)}; consulta abajo las fechas y el precio, y en la ficha el contenido completo en texto" width="750" height="1000" loading="lazy"><span>Ver fotos y cartel completo ↗</span></a><div><p class="eyebrow">${e(t.type)}</p><h3>${e(t.hotel)}</h3><p>${range(t)}</p><p class="brochure-price">${money(t.price)} <small>MXN · referencia publicada</small></p><a class="text-link" href="/viajes/${id}/">Qué incluye este viaje →</a></div></article>`}).join('')}</div></div></section>`}
export const tourSection=()=>`<section class="wrap section tour-section" id="tour-tampico"><div class="tour-poster"><a href="/assets/cartel-tampico.jpg" target="_blank" rel="noopener"><img src="/assets/cartel-tampico.jpg" alt="Cartel de Tampico, 15 y 16 de septiembre; transcripción de servicios al lado" width="525" height="700" loading="lazy">Ampliar cartel en otra pestaña ↗</a></div><div><p class="eyebrow">TOURS Y ESCAPADAS</p><h2>Una escapada a Tampico</h2><p>Río Vista Inn · 15 y 16 de septiembre de 2026 · 2 días / 1 noche.</p><h3>Qué publica el cartel</h3><ul><li>Autobús de primera y hospedaje en Río Vista Inn.</li><li>Dos desayunos buffet: martes y miércoles.</li><li>Coordinador de viaje y seguro de pasajero dentro de la unidad.</li><li>Visitas al centro histórico, escolleras y Playa Sirenas.</li><li>Salida el 14 de septiembre a las 11:45 p. m.</li></ul><p class="notice">Precio pendiente de aclaración: el catálogo muestra $2,300; el cartel publica desde $2,199 por persona en ocupación triple o cuádruple, $2,299 doble, $2,999 sencilla y $1,600 para menores de 3 a 11 años. La agencia debe confirmar la tarifa y el año de este cartel antes de reservar.</p><p class="muted">El cartel indica que el itinerario puede cambiar por clima, tráfico o indicaciones de las autoridades. Impuestos, exclusiones y condiciones completas por confirmar.</p><a class="button" href="/contacto/?experiencia=tours&tour=tampico">Consultar este tour ↗</a></div></section>`;
export function detailFlyer(t){const f=flyers[t.id];return f?`<section class="wrap section original-flyer" id="cartel"><div><p class="eyebrow">PUBLICACIÓN ORIGINAL DE CIELOAZUL</p><h2>Las fotos y los detalles del paquete</h2><p>Abre la imagen completa para ver el hotel y la información publicada por la agencia.</p><h3>Contenido del cartel en texto</h3><p>${e(f.text)}</p><p class="muted">Información observada en el cartel el 12 de septiembre de 2026; confirmar vigencia antes de reservar.</p><a class="button" href="/contacto/?viaje=${t.id}">Cotizar este viaje ↗</a></div><a class="full-poster" href="/assets/${f.file}" target="_blank" rel="noopener"><img src="/assets/${f.file}" alt="Cartel original de ${e(t.hotel)}, ${range(t)}; contenido transcrito en esta sección" width="750" height="1000" loading="lazy"><span>Ampliar cartel en otra pestaña ↗</span></a></section>`:''}
